    comp->dither.gleen_bitdepth = 6;
    comp->dither.blue_bitdepth = 6;
    comp->dither.enable = 1;
    break;
  default:
    memset(&comp->dither, 0x00, sizeof(struct aic_de_dither));
    break;
  }

  return 0;
}

