  struct aic_de_comp *comp = aic_de_request_drvdata();

  if (is_support_alpha_blending(comp, alpha->layer_id) == false) {
    pr_err("layer %d doesn't support alpha blending\n", alpha->layer_id);
    aic_de_release_drvdata();
