struct aic_pwm_lowerhalf_s {
  struct pwm_lowerhalf_s dev;
  int pwm_id;
  mutex_t lock;
  int refs;
#ifdef CONFIG_PWM_MULTICHAN
  struct pwm_chan_s channels[CONFIG_PWM_NCHANNELS];
