  struct aicfb_info *fbi = aicfb_get_drvdata();
  unsigned long offset, size;

  if (!vtable || !fbi || !area)
    return -EINVAL;

  /* 计算区域偏移和大小 */
  offset = (area->y * fbi->stride) + (area->x * (fbi->bits_per_pixel / 8));
